// PublicBlogIndexQuery are the optional query parameters of PublicBlogService.Index.
type PublicBlogIndexQuery struct {
	// Articles per page.
	Limit    *int64
	Tag      *string
	AuthorID *string
	Author   *string
	Series   *string
	Month    *string
	// Which page of results to return, 1-based.
	Page   *int64
	Cursor *string
	Share  *string
	// Use true or false (true/1/yes/on and false/0/no/off are accepted).
	Pinned *string
	// Use true or false (true/1/yes/on and false/0/no/off are accepted).
	Featured *string
	Preview  *string
	Tags     *string
	TagMatch *string
	// Comma-separated post ids to leave out — a front page’s feeds de-duplicating each other.
	Exclude []string
	// Skip this many posts before the page starts (added to the page’s own offset).
	Offset *int64
	Locale *string
	Sort   *string
}

func (p *PublicBlogIndexQuery) encode(opts []RequestOption) (url.Values, []RequestOption) {
	v := url.Values{}
	if p == nil {
		return v, opts
	}
	if p.Limit != nil {
		v.Set("limit", strconv.FormatInt(*p.Limit, 10))
	}
	if p.Tag != nil {
		v.Set("tag", *p.Tag)
	}
	if p.AuthorID != nil {
		v.Set("authorId", *p.AuthorID)
	}
	if p.Author != nil {
		v.Set("author", *p.Author)
	}
	if p.Series != nil {
		v.Set("series", *p.Series)
	}
	if p.Month != nil {
		v.Set("month", *p.Month)
	}
	if p.Page != nil {
		v.Set("page", strconv.FormatInt(*p.Page, 10))
	}
	if p.Cursor != nil {
		v.Set("cursor", *p.Cursor)
	}
	if p.Share != nil {
		v.Set("share", *p.Share)
	}
	if p.Pinned != nil {
		v.Set("pinned", *p.Pinned)
	}
	if p.Featured != nil {
		v.Set("featured", *p.Featured)
	}
	if p.Preview != nil {
		v.Set("preview", *p.Preview)
	}
	if p.Tags != nil {
		v.Set("tags", *p.Tags)
	}
	if p.TagMatch != nil {
		v.Set("tagMatch", *p.TagMatch)
	}
	for _, x := range p.Exclude {
		v.Add("exclude", x)
	}
	if p.Offset != nil {
		v.Set("offset", strconv.FormatInt(*p.Offset, 10))
	}
	if p.Locale != nil {
		v.Set("locale", *p.Locale)
	}
	if p.Sort != nil {
		v.Set("sort", *p.Sort)
	}
	return v, opts
}

